// QTM321 — Học máy lượng tử (nối tiếp QTC211). Trường chưa công bố syllabus trên FLM (dò 09/11/2026); khung theo Schuld-Petruccione, Nielsen-Chuang.
// Dựng khung bằng $TMPDIR/khung-b — bài chỉ gồm mục tiêu, khái niệm then chốt, link học ngoài (đã kiểm HTTP 200 + tiêu đề), ý chính.
// Không dùng chuỗi nội suy hay backtick; văn bản thuần được escape khi dựng HTML.
const E = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const UL = (s) => '<ul>' + s.split(' ¦ ').map((x) => '<li>' + E(x.trim()) + '</li>').join('') + '</ul>';
const LK = (a, i) => '<ul>' + a.map((x) => '<li><a href="' + x[0].replace(/&/g, '&amp;') + '" target="_blank" rel="noopener">' + E(x[1]) + '</a> — ' + E(x[2 + i]) + '</li>').join('') + '</ul>';
const H = ['<h3>🎯 Objectives</h3>', '<h3>📖 What you will learn</h3>', '<h3>🔗 Where to learn</h3>', '<h3>📌 Key points</h3>'];
const HV = ['<h3>🎯 Mục tiêu</h3>', '<h3>📖 Học gì</h3>', '<h3>🔗 Học ở đâu</h3>', '<h3>📌 Ý chính</h3>'];
const BI = (en, vi) => '<div class="ml-en">' + en + '</div>\n<div class="ml-vi">' + vi + '</div>';
const MA = 'qtm321';
const L = (slug, t, oe, ov, ke, kv, pe, pv, links) => ({
  title: t[0] + '|||' + t[1], slug, type: 'DOCUMENT',
  description: 'Khung bài (chế độ khung): ' + t[1] + ' — mục tiêu, khái niệm then chốt và nguồn học ngoài.',
  content: BI(H[0] + UL(oe) + H[1] + UL(ke) + H[2] + LK(links, 0) + H[3] + UL(pe), HV[0] + UL(ov) + HV[1] + UL(kv) + HV[2] + LK(links, 1) + HV[3] + UL(pv)),
});
const C = (n, t, desc, ls) => ({ title: 'Chapter ' + n + ' — ' + t[0] + '|||Chương ' + n + ' — ' + t[1], description: desc,
  lessons: ls.map((a, i) => L(MA + '-ts-' + n + '-' + (i + 1), a[0], a[1], a[2], a[3], a[4], a[5], a[6], a[7])) });
const S0 = (t, desc, ls) => ({ title: 'Section 0 — Course framework (self-authored, no FLM syllabus)|||Mục 0 — Khung môn học (tự soạn, trường chưa công bố syllabus)', description: desc,
  lessons: ls.map((a, i) => L(MA + '-ts-0-' + (i + 1), a[0], a[1], a[2], a[3], a[4], a[5], a[6], a[7])) });

const YT = (id) => 'https://www.youtube.com/watch?v=' + id;
const AX = (id) => 'https://arxiv.org/abs/' + id;
const PL = (id) => 'https://pennylane.ai/qml/demos/' + id;
export default [
  S0(null, 'Giới thiệu môn QTM321 và giáo trình. Trường chưa công bố syllabus trên FLM nên khung này tự soạn, nối tiếp QTC211 (đã học qubit, cổng, mạch và Qiskit).', [
    [['Welcome to QTM321: Quantum Machine Learning', 'Giới thiệu QTM321: Học máy lượng tử'],
      'Know what the course covers and what it assumes from QTC211 ¦ List the learning outcomes ¦ Understand how this frame was built',
      'Biết môn học bao quát gì và cần gì từ QTC211 ¦ Nắm các chuẩn đầu ra tự soạn ¦ Hiểu khung này được dựng thế nào',
      'QTM321 follows QTC211 (complex linear algebra, qubits, gates, circuits, entanglement, basic algorithms and Qiskit practice). Here we ask how quantum circuits can serve machine learning: encoding data in quantum states, quantum kernels, variational circuits and quantum neural networks, gradient-based training and its obstacles (barren plateaus, noise), quantum linear algebra, generative models, optimisation with QAOA, and an honest look at quantum advantage. Self-authored outcomes: (1) encode classical data into circuits ¦ (2) build and evaluate a quantum kernel classifier ¦ (3) train a variational circuit with parameter-shift gradients ¦ (4) compose hybrid quantum-classical networks ¦ (5) explain HHL, qPCA and dequantization ¦ (6) formulate QUBO problems for QAOA ¦ (7) benchmark against classical baselines ¦ (8) judge claims of advantage. WARNING: FPTU has not published the QTM321 syllabus on FLM. This outline follows Schuld-Petruccione, Nielsen-Chuang and the Qiskit/PennyLane material; grading and exam schedule follow your lecturer.',
      'QTM321 nối tiếp QTC211 (đại số tuyến tính phức, qubit, cổng, mạch, vướng víu, thuật toán cơ bản và thực hành Qiskit). Ở đây ta hỏi mạch lượng tử phục vụ học máy thế nào: mã hoá dữ liệu vào trạng thái lượng tử, kernel lượng tử, mạch biến phân và mạng nơ-ron lượng tử, huấn luyện bằng gradient và trở ngại của nó (cao nguyên cằn cỗi, nhiễu), đại số tuyến tính lượng tử, mô hình sinh, tối ưu bằng QAOA và cái nhìn trung thực về lợi thế lượng tử. Chuẩn đầu ra tự soạn: (1) mã hoá dữ liệu cổ điển vào mạch ¦ (2) dựng và đánh giá bộ phân loại kernel lượng tử ¦ (3) huấn luyện mạch biến phân bằng gradient parameter-shift ¦ (4) ghép mạng lai lượng tử-cổ điển ¦ (5) giải thích HHL, qPCA và phi lượng tử hoá ¦ (6) lập công thức QUBO cho QAOA ¦ (7) so sánh với mốc cổ điển ¦ (8) đánh giá các tuyên bố lợi thế. ⚠️ Trường chưa công bố syllabus QTM321 trên FLM. Khung này theo Schuld-Petruccione, Nielsen-Chuang và tài liệu Qiskit/PennyLane; cách tính điểm và lịch thi theo giảng viên.',
      'QML builds on QTC211 circuits ¦ Variational and kernel methods are the core ¦ Be critical about advantage claims',
      'QML dựng trên mạch của QTC211 ¦ Phương pháp biến phân và kernel là lõi ¦ Phê phán các tuyên bố lợi thế',
      [[AX('1611.09347'), 'Biamonte et al.: Quantum Machine Learning', 'Read the introduction for the field overview.', 'Đọc phần mở đầu để có bức tranh tổng thể.'],
       ['https://pennylane.ai/qml/', 'PennyLane: Learn quantum programming', 'Skim the learning paths.', 'Lướt các lộ trình học.']]],
    [['Textbooks and learning resources', 'Giáo trình và tài liệu học'],
      'Pick a main book and free companions ¦ Know the software stack',
      'Chọn sách chính và tài liệu miễn phí đi kèm ¦ Biết bộ phần mềm',
      'Books: Maria Schuld and Francesco Petruccione, Machine Learning with Quantum Computers, 2nd ed., Springer 2021, ISBN 9783030830977 ¦ Michael Nielsen and Isaac Chuang, Quantum Computation and Quantum Information, 10th anniversary ed., Cambridge University Press 2010, ISBN 9781107002173 ¦ Free classical background: Mathematics for Machine Learning (Deisenroth, Faisal, Ong) and Dive into Deep Learning. Software: Qiskit with the Qiskit Machine Learning package, PennyLane (with PyTorch), TensorFlow Quantum. Courses: PennyLane demos and Codebook, Qiskit Global Summer School lectures, Quantum Country.',
      'Sách: Maria Schuld và Francesco Petruccione, Machine Learning with Quantum Computers, ấn bản 2, Springer 2021, ISBN 9783030830977 ¦ Michael Nielsen và Isaac Chuang, Quantum Computation and Quantum Information, ấn bản kỷ niệm 10 năm, Cambridge University Press 2010, ISBN 9781107002173 ¦ Nền cổ điển miễn phí: Mathematics for Machine Learning (Deisenroth, Faisal, Ong) và Dive into Deep Learning. Phần mềm: Qiskit cùng gói Qiskit Machine Learning, PennyLane (với PyTorch), TensorFlow Quantum. Khoá học: PennyLane demos và Codebook, bài giảng Qiskit Global Summer School, Quantum Country.',
      'Use Schuld-Petruccione as the main book ¦ Practise in PennyLane and Qiskit ¦ Review classical ML with free books',
      'Dùng Schuld-Petruccione làm sách chính ¦ Thực hành bằng PennyLane và Qiskit ¦ Ôn ML cổ điển bằng sách miễn phí',
      [['https://mml-book.github.io/', 'Mathematics for Machine Learning', 'Free book: read linear algebra and optimisation chapters.', 'Sách miễn phí: đọc các chương đại số tuyến tính và tối ưu.'],
       ['https://pennylane.ai/codebook/', 'PennyLane Codebook', 'Interactive quantum programming exercises.', 'Bài tập lập trình lượng tử tương tác.'],
       ['https://github.com/qiskit-community/qiskit-machine-learning', 'Qiskit Machine Learning (GitHub)', 'Read the README and the tutorials folder.', 'Đọc README và thư mục tutorials.'],
       ['https://www.tensorflow.org/quantum', 'TensorFlow Quantum', 'Skim the overview and tutorials list.', 'Lướt tổng quan và danh sách hướng dẫn.']]],
  ]),

  C(1, ['Foundations of quantum machine learning', 'Nền tảng học máy lượng tử'], 'Bức tranh QML, ôn học máy cổ điển và công cụ phần mềm.', [
    [['The QML landscape: four approaches and NISQ', 'Bức tranh QML: bốn cách tiếp cận và kỷ nguyên NISQ'],
      'Classify CC, CQ, QC and QQ settings ¦ Explain the NISQ constraint',
      'Phân loại bối cảnh CC, CQ, QC và QQ ¦ Giải thích ràng buộc NISQ',
      'Quantum machine learning mixes data type (classical or quantum) and processing (classical or quantum) ¦ Most near-term work is classical data processed by quantum circuits ¦ NISQ devices have tens to hundreds of noisy qubits and no error correction, so shallow hybrid algorithms dominate ¦ Promised benefits: expressive feature spaces, faster linear algebra ¦ Open questions: loading data, trainability, genuine advantage.',
      'Học máy lượng tử trộn kiểu dữ liệu (cổ điển hay lượng tử) và cách xử lý (cổ điển hay lượng tử) ¦ Phần lớn công trình gần hạn là dữ liệu cổ điển xử lý bằng mạch lượng tử ¦ Thiết bị NISQ có hàng chục đến hàng trăm qubit nhiễu và không sửa lỗi nên thuật toán lai nông chiếm ưu thế ¦ Lợi ích hứa hẹn: không gian đặc trưng giàu biểu đạt, đại số tuyến tính nhanh hơn ¦ Câu hỏi mở: nạp dữ liệu, khả năng huấn luyện, lợi thế thật sự.',
      'Most QML is classical data on quantum circuits ¦ NISQ favours shallow hybrid methods ¦ Advantage is still open',
      'Phần lớn QML là dữ liệu cổ điển trên mạch lượng tử ¦ NISQ ưu tiên phương pháp lai nông ¦ Lợi thế vẫn còn bỏ ngỏ',
      [[AX('1611.09347'), 'Biamonte et al.: Quantum Machine Learning', 'Read sections on quantum speedups and challenges.', 'Đọc các mục về tăng tốc lượng tử và thách thức.'],
       [AX('1801.00862'), 'Preskill: Quantum Computing in the NISQ Era and Beyond', 'Read the introduction and the NISQ definition.', 'Đọc phần mở đầu và định nghĩa NISQ.'],
       [AX('1409.3097'), 'Schuld et al.: An introduction to quantum machine learning', 'Read the overview of approaches.', 'Đọc tổng quan các cách tiếp cận.'],
       [YT('VVY8xcps3N4'), 'Schuld: How to rethink quantum machine learning (IPAM)', 'Watch for the research perspective.', 'Xem để có góc nhìn nghiên cứu.']]],
    [['Classical machine learning refresher: loss, gradients and kernels', 'Ôn học máy cổ điển: hàm mất mát, gradient và kernel'],
      'Write a loss and its gradient step ¦ Explain linear models and kernel methods',
      'Viết hàm mất mát và bước gradient ¦ Giải thích mô hình tuyến tính và phương pháp kernel',
      'Supervised learning minimises a loss over parameters, e.g. squared error ¦ Gradient descent updates theta ← theta - η ∇L(theta) ¦ Overfitting, regularisation and train/validation/test splits apply unchanged to quantum models ¦ Kernel methods compute similarity k(x, x\') as an inner product in a feature space, and SVMs use it ¦ Quantum models can be seen as linear models in a huge Hilbert space.',
      'Học có giám sát cực tiểu hoá hàm mất mát theo tham số, ví dụ sai số bình phương ¦ Hạ gradient cập nhật theta ← theta - η ∇L(theta) ¦ Quá khớp, điều chuẩn và chia train/validation/test áp dụng y nguyên cho mô hình lượng tử ¦ Phương pháp kernel tính độ tương tự k(x, x\') như tích trong trong không gian đặc trưng và SVM dùng nó ¦ Mô hình lượng tử có thể xem là mô hình tuyến tính trong không gian Hilbert khổng lồ.',
      'Quantum ML reuses classical training ideas ¦ Gradient descent updates parameters ¦ Kernels are inner products',
      'ML lượng tử dùng lại ý tưởng huấn luyện cổ điển ¦ Hạ gradient cập nhật tham số ¦ Kernel là tích trong',
      [['https://mml-book.github.io/book/mml-book.pdf', 'Mathematics for Machine Learning (PDF)', 'Read chapter 7 on continuous optimisation.', 'Đọc chương 7 về tối ưu liên tục.'],
       ['https://d2l.ai/chapter_optimization/gd.html', 'Dive into Deep Learning: gradient descent', 'Read the page with the plots.', 'Đọc trang cùng biểu đồ.'],
       ['https://scikit-learn.org/stable/modules/svm.html#kernel-functions', 'scikit-learn: SVM kernel functions', 'Read the kernel list.', 'Đọc danh sách kernel.'],
       ['https://cs229.stanford.edu/main_notes.pdf', 'Stanford CS229 lecture notes', 'Read the SVM and kernels notes.', 'Đọc ghi chú về SVM và kernel.']]],
    [['Software stack: Qiskit Machine Learning, PennyLane and TensorFlow Quantum', 'Bộ phần mềm: Qiskit Machine Learning, PennyLane và TensorFlow Quantum'],
      'Run a first hybrid model ¦ Choose a framework for a task',
      'Chạy mô hình lai đầu tiên ¦ Chọn framework cho từng việc',
      'Qiskit Machine Learning offers quantum kernels, QNNs and classifiers/regressors compatible with scikit-learn and PyTorch ¦ PennyLane differentiates quantum circuits automatically and plugs into PyTorch, JAX and TensorFlow ¦ TensorFlow Quantum embeds circuits as Keras layers ¦ Simulators are exact but cost grows exponentially with qubits ¦ Always fix seeds and shots for reproducible results.',
      'Qiskit Machine Learning cung cấp kernel lượng tử, QNN và bộ phân loại/hồi quy tương thích scikit-learn và PyTorch ¦ PennyLane tự động đạo hàm mạch lượng tử và nối với PyTorch, JAX, TensorFlow ¦ TensorFlow Quantum nhúng mạch thành lớp Keras ¦ Bộ mô phỏng chính xác nhưng chi phí tăng theo cấp số mũ với số qubit ¦ Luôn cố định seed và số shot để kết quả tái lập.',
      'Three major frameworks ¦ Automatic differentiation is built in ¦ Simulation cost doubles per qubit',
      'Ba framework chính ¦ Tự động đạo hàm có sẵn ¦ Chi phí mô phỏng gấp đôi mỗi qubit',
      [[PL('tutorial_qubit_rotation'), 'PennyLane: qubit rotation tutorial', 'Run your first optimisation of a circuit.', 'Chạy lần tối ưu mạch đầu tiên.'],
       [PL('tutorial_qnn_module_torch'), 'PennyLane: quantum nodes as Torch layers', 'Follow the hybrid model example.', 'Làm theo ví dụ mô hình lai.'],
       [AX('2003.02989'), 'TensorFlow Quantum paper', 'Read the framework overview.', 'Đọc tổng quan framework.'],
       ['https://docs.pennylane.ai/en/stable/introduction/interfaces/torch.html', 'PennyLane PyTorch interface', 'Read how gradients flow.', 'Đọc cách gradient lan truyền.']]],
  ]),

  C(2, ['Encoding classical data into quantum states', 'Mã hoá dữ liệu cổ điển vào trạng thái lượng tử'], 'Mã hoá cơ sở, biên độ, góc, bản đồ đặc trưng và biểu đạt của mã hoá.', [
    [['Basis and amplitude encoding', 'Mã hoá cơ sở và mã hoá biên độ'],
      'Encode bit strings and normalised vectors ¦ Compare qubit counts and circuit cost',
      'Mã hoá chuỗi bit và vector chuẩn hoá ¦ So số qubit và chi phí mạch',
      'Basis encoding maps the bit string x to the computational basis state |x> and uses n qubits for n bits ¦ Amplitude encoding stores a normalised vector in the amplitudes of log2(N) qubits: 2^n numbers in n qubits ¦ State preparation circuits for arbitrary amplitudes are deep, so the exponential saving is often lost in loading ¦ Always normalise the vector first.',
      'Mã hoá cơ sở ánh xạ chuỗi bit x thành trạng thái cơ sở tính toán |x> và dùng n qubit cho n bit ¦ Mã hoá biên độ lưu vector chuẩn hoá trong biên độ của log2(N) qubit: 2^n số trong n qubit ¦ Mạch chuẩn bị trạng thái cho biên độ tuỳ ý rất sâu nên lợi thế mũ thường mất ở khâu nạp ¦ Luôn chuẩn hoá vector trước.',
      'Amplitude encoding is qubit-efficient ¦ State preparation can be expensive ¦ Normalise inputs',
      'Mã hoá biên độ tiết kiệm qubit ¦ Chuẩn bị trạng thái có thể đắt ¦ Chuẩn hoá đầu vào',
      [[YT('LHzWAyT5rMI'), 'Quantum Machine Learning 24: Encoding classical information', 'Watch basis and amplitude encoding.', 'Xem mã hoá cơ sở và biên độ.'],
       ['https://docs.pennylane.ai/en/stable/code/api/pennylane.AmplitudeEmbedding.html', 'PennyLane AmplitudeEmbedding', 'Read the parameters and examples.', 'Đọc tham số và ví dụ.'],
       [AX('1803.07128'), 'Schuld and Killoran: QML in feature Hilbert spaces', 'Read the section on encoding data.', 'Đọc mục về mã hoá dữ liệu.']]],
    [['Angle encoding and feature maps (ZFeatureMap, ZZFeatureMap)', 'Mã hoá góc và bản đồ đặc trưng (ZFeatureMap, ZZFeatureMap)'],
      'Build an angle-encoding circuit ¦ Explain entangling feature maps',
      'Dựng mạch mã hoá góc ¦ Giải thích bản đồ đặc trưng có vướng víu',
      'Angle encoding uses one rotation per feature, e.g. RY(x_i) on qubit i: n features need n qubits and constant depth ¦ Feature maps repeat encoding layers with Hadamards and entangling gates, as in ZZFeatureMap, to create correlations between features ¦ The map phi(x) defines the quantum feature space and a kernel k(x, x\') = |<phi(x)|phi(x\')>|² ¦ Rescale features to a sensible angle range.',
      'Mã hoá góc dùng một phép quay cho mỗi đặc trưng, ví dụ RY(x_i) trên qubit i: n đặc trưng cần n qubit và độ sâu hằng ¦ Bản đồ đặc trưng lặp các lớp mã hoá với Hadamard và cổng vướng víu, như ZZFeatureMap, để tạo tương quan giữa đặc trưng ¦ Ánh xạ phi(x) định nghĩa không gian đặc trưng lượng tử và kernel k(x, x\') = |<phi(x)|phi(x\')>|² ¦ Đổi tỉ lệ đặc trưng về khoảng góc hợp lý.',
      'One rotation per feature ¦ Entangling layers add expressivity ¦ Scale features to angles',
      'Một phép quay cho mỗi đặc trưng ¦ Lớp vướng víu tăng biểu đạt ¦ Đổi tỉ lệ đặc trưng về góc',
      [[AX('1804.11326'), 'Havlicek et al.: Supervised learning with quantum-enhanced feature spaces', 'Read the feature map definition.', 'Đọc định nghĩa bản đồ đặc trưng.'],
       ['https://docs.pennylane.ai/en/stable/code/api/pennylane.AngleEmbedding.html', 'PennyLane AngleEmbedding', 'Read the rotation options.', 'Đọc các tuỳ chọn phép quay.'],
       [YT('N-l4wQY5kzM'), 'Qiskit Lecture 4.1: Introduction to classical ML', 'Watch as preparation for data encoding.', 'Xem để chuẩn bị cho mã hoá dữ liệu.'],
       [YT('lpPij21jnZ4'), 'Qiskit Lecture 4.2: Advanced classical ML', 'Watch the kernel and feature map links.', 'Xem phần liên hệ kernel và bản đồ đặc trưng.']]],
    [['Expressivity of encodings and data re-uploading', 'Biểu đạt của mã hoá và nạp lại dữ liệu'],
      'Explain quantum models as Fourier series ¦ Use data re-uploading',
      'Giải thích mô hình lượng tử như chuỗi Fourier ¦ Dùng nạp lại dữ liệu',
      'A circuit that encodes x with Pauli rotations produces a function that is a Fourier series in x, with frequencies fixed by the encoding gates ¦ Repeating the encoding (data re-uploading) increases the accessible frequencies and the expressive power ¦ Trainable blocks between encodings choose the Fourier coefficients ¦ Encoding is therefore a model choice, not a preprocessing detail.',
      'Mạch mã hoá x bằng phép quay Pauli cho hàm là chuỗi Fourier theo x, với tần số do cổng mã hoá quy định ¦ Lặp lại mã hoá (nạp lại dữ liệu) tăng tần số khả dụng và sức biểu đạt ¦ Các khối huấn luyện được giữa các lần mã hoá chọn hệ số Fourier ¦ Vì vậy mã hoá là lựa chọn mô hình, không phải chi tiết tiền xử lý.',
      'Encoding fixes the frequency spectrum ¦ Re-uploading enriches the model ¦ Choose encodings deliberately',
      'Mã hoá cố định phổ tần số ¦ Nạp lại làm giàu mô hình ¦ Chọn mã hoá có chủ đích',
      [[AX('2008.08605'), 'Schuld et al.: Effect of data encoding on expressive power', 'Read the abstract and the Fourier series result.', 'Đọc tóm tắt và kết quả chuỗi Fourier.'],
       [PL('tutorial_expressivity_fourier_series'), 'PennyLane: Quantum models as Fourier series', 'Run the demo.', 'Chạy bản demo.'],
       [PL('tutorial_data_reuploading_classifier'), 'PennyLane: Data re-uploading classifier', 'Run the demo.', 'Chạy bản demo.']]],
    [['The cost of loading data: state preparation and QRAM', 'Chi phí nạp dữ liệu: chuẩn bị trạng thái và QRAM'],
      'Explain why input cost can erase speedups ¦ Describe QRAM and its caveats',
      'Giải thích vì sao chi phí đầu vào có thể xoá lợi thế ¦ Mô tả QRAM và lưu ý',
      'Preparing an arbitrary N-amplitude state takes about N gates in general, which removes exponential speedups ¦ QRAM would give O(log N) access to memory in superposition, but needs a large fault-tolerant hardware structure that does not exist yet ¦ Structured data (sparse, low-rank, efficiently integrable distributions) can be loaded faster ¦ Always include loading and read-out costs when claiming a speedup.',
      'Chuẩn bị trạng thái N biên độ tuỳ ý nói chung cần khoảng N cổng, làm mất tăng tốc mũ ¦ QRAM cho truy cập bộ nhớ O(log N) trong chồng chập nhưng cần cấu trúc phần cứng chịu lỗi lớn mà chưa tồn tại ¦ Dữ liệu có cấu trúc (thưa, hạng thấp, phân phối tích phân hiệu quả) nạp nhanh hơn ¦ Luôn tính chi phí nạp và đọc ra khi tuyên bố tăng tốc.',
      'Loading can dominate the runtime ¦ QRAM is not available today ¦ Count input and output costs',
      'Nạp dữ liệu có thể chiếm phần lớn thời gian ¦ QRAM chưa có ngày nay ¦ Tính chi phí đầu vào và đầu ra',
      [[AX('1611.09347'), 'Biamonte et al.: Quantum Machine Learning', 'Read the discussion of input problems.', 'Đọc thảo luận về vấn đề đầu vào.'],
       [AX('1807.04271'), 'Tang: quantum-inspired recommendation algorithm', 'Read the abstract on sampling access.', 'Đọc tóm tắt về truy cập lấy mẫu.'],
       [YT('LHzWAyT5rMI'), 'Quantum Machine Learning 24: Encoding', 'Watch the cost discussion.', 'Xem phần thảo luận chi phí.']]],
  ]),

  C(3, ['Quantum kernel methods', 'Phương pháp kernel lượng tử'], 'Kernel lượng tử, ước lượng bằng mạch, huấn luyện kernel và giới hạn lợi thế.', [
    [['Kernel methods and the quantum feature space', 'Phương pháp kernel và không gian đặc trưng lượng tử'],
      'State the kernel trick ¦ View a quantum state as a feature vector',
      'Phát biểu mẹo kernel ¦ Xem trạng thái lượng tử như vector đặc trưng',
      'A kernel k(x, x\') equals an inner product of feature vectors, letting algorithms work in huge spaces implicitly ¦ A quantum feature map sends x to the state |phi(x)> in Hilbert space ¦ The fidelity kernel is k(x, x\') = |<phi(x)|phi(x\')>|² ¦ Supervised quantum models are kernel methods: the model is a linear function in the feature space (Schuld 2021).',
      'Kernel k(x, x\') bằng tích trong của vector đặc trưng, cho thuật toán làm việc ngầm trong không gian khổng lồ ¦ Bản đồ đặc trưng lượng tử đưa x tới trạng thái |phi(x)> trong không gian Hilbert ¦ Kernel độ trung thực là k(x, x\') = |<phi(x)|phi(x\')>|² ¦ Mô hình lượng tử có giám sát là phương pháp kernel: mô hình là hàm tuyến tính trong không gian đặc trưng (Schuld 2021).',
      'Kernels hide the feature space ¦ Quantum states are feature vectors ¦ Fidelity gives the kernel',
      'Kernel giấu không gian đặc trưng ¦ Trạng thái lượng tử là vector đặc trưng ¦ Độ trung thực cho kernel',
      [[AX('2101.11020'), 'Schuld: Supervised quantum machine learning models are kernel methods', 'Read the introduction and main claim.', 'Đọc phần mở đầu và khẳng định chính.'],
       [YT('uDAAi5aQbMU'), 'Quantum ML 32: Quantum-enhanced kernel methods 1 (Schuld)', 'Watch the first part.', 'Xem phần đầu.'],
       ['https://scikit-learn.org/stable/auto_examples/svm/plot_svm_kernels.html', 'scikit-learn: SVM kernels', 'Compare classical kernels.', 'So các kernel cổ điển.']]],
    [['Estimating a quantum kernel and building a QSVC', 'Ước lượng kernel lượng tử và dựng QSVC'],
      'Estimate a kernel entry with a compute-uncompute circuit ¦ Train an SVM on a precomputed kernel',
      'Ước lượng một phần tử kernel bằng mạch compute-uncompute ¦ Huấn luyện SVM trên kernel tính sẵn',
      'Each kernel entry is estimated by running U(x\') followed by U(x) dagger and measuring the probability of the all-zero outcome ¦ The Gram matrix over N training points needs about N²/2 circuit evaluations ¦ Feed the matrix to a classical SVM with kernel precomputed ¦ Finite shots add statistical noise, so the matrix may not be positive semidefinite ¦ Qiskit Machine Learning packages this as QSVC.',
      'Mỗi phần tử kernel được ước lượng bằng chạy U(x\') rồi U(x) liên hợp và đo xác suất kết quả toàn không ¦ Ma trận Gram trên N điểm huấn luyện cần khoảng N²/2 lần chạy mạch ¦ Đưa ma trận vào SVM cổ điển với kernel tính sẵn ¦ Số shot hữu hạn gây nhiễu thống kê nên ma trận có thể không nửa xác định dương ¦ Qiskit Machine Learning đóng gói thành QSVC.',
      'Overlap circuits estimate entries ¦ The Gram matrix grows quadratically ¦ Shot noise needs care',
      'Mạch chồng lấn ước lượng phần tử ¦ Ma trận Gram tăng bậc hai ¦ Nhiễu shot cần lưu ý',
      [[PL('tutorial_kernel_based_training'), 'PennyLane: kernel-based training with scikit-learn', 'Run the demo end to end.', 'Chạy bản demo từ đầu đến cuối.'],
       [YT('LmQcSxgINis'), 'Qiskit Lecture 7.1: Quantum kernels in practice', 'Watch the implementation walkthrough.', 'Xem hướng dẫn cài đặt.'],
       [YT('zw3JYUrS-v8'), 'Qiskit Lecture 6.2: Quantum feature spaces and kernels', 'Watch the theory.', 'Xem phần lý thuyết.'],
       ['https://github.com/qiskit-community/qiskit-machine-learning/tree/main/docs/tutorials', 'Qiskit Machine Learning tutorials', 'Open the quantum kernel notebooks.', 'Mở các notebook kernel lượng tử.']]],
    [['Trainable kernels and kernel alignment', 'Kernel huấn luyện được và độ căn chỉnh kernel'],
      'Parametrise a feature map ¦ Optimise kernel-target alignment',
      'Tham số hoá bản đồ đặc trưng ¦ Tối ưu căn chỉnh kernel-đích',
      'A fixed feature map may suit the data poorly ¦ Adding trainable parameters to the map gives a family of kernels ¦ Kernel-target alignment measures how well the Gram matrix matches the label matrix and can be optimised without training the SVM each step ¦ Beware of exponential concentration: kernels on many qubits can become almost constant and useless ¦ Use bandwidth scaling.',
      'Bản đồ đặc trưng cố định có thể hợp dữ liệu kém ¦ Thêm tham số huấn luyện được cho bản đồ tạo ra họ kernel ¦ Căn chỉnh kernel-đích đo ma trận Gram khớp ma trận nhãn tốt đến đâu và tối ưu được mà không huấn luyện SVM mỗi bước ¦ Coi chừng tập trung mũ: kernel trên nhiều qubit có thể gần như hằng và vô dụng ¦ Dùng co giãn băng thông.',
      'Trainable maps adapt to data ¦ Alignment guides training ¦ Kernel concentration is a risk',
      'Bản đồ huấn luyện được thích nghi dữ liệu ¦ Căn chỉnh dẫn huấn luyện ¦ Tập trung kernel là rủi ro',
      [[PL('tutorial_kernels_module'), 'PennyLane: training and evaluating quantum kernels', 'Follow the kernel-target alignment section.', 'Làm theo phần căn chỉnh kernel-đích.'],
       [AX('2001.03622'), 'Lloyd et al.: Quantum embeddings for machine learning', 'Read the abstract on trainable embeddings.', 'Đọc tóm tắt về embedding huấn luyện được.'],
       [YT('pfGHJivyzHA'), 'Quantum ML 33: Quantum-enhanced kernel methods 2', 'Watch the continuation.', 'Xem phần tiếp theo.']]],
    [['When do quantum kernels help? The power of data', 'Khi nào kernel lượng tử có ích? Sức mạnh của dữ liệu'],
      'Summarise the power-of-data argument ¦ Compare against classical kernels',
      'Tóm tắt lập luận sức mạnh của dữ liệu ¦ So với kernel cổ điển',
      'Huang et al. show that with enough training data, classical models can learn functions that look hard for classical computers if the data come from a quantum process, so data matter as much as the model ¦ A geometric measure compares quantum and classical kernels and tells when a quantum advantage is plausible ¦ Rigorous speedups exist for contrived problems based on the discrete logarithm ¦ On real tabular data, classical kernels remain very strong baselines.',
      'Huang và cộng sự chỉ ra rằng với đủ dữ liệu huấn luyện, mô hình cổ điển học được cả hàm trông khó với máy tính cổ điển nếu dữ liệu đến từ quá trình lượng tử, nên dữ liệu quan trọng ngang mô hình ¦ Một độ đo hình học so kernel lượng tử và cổ điển, cho biết khi nào lợi thế lượng tử khả dĩ ¦ Tăng tốc nghiêm ngặt tồn tại cho bài toán nhân tạo dựa trên logarit rời rạc ¦ Trên dữ liệu bảng thật, kernel cổ điển vẫn là mốc rất mạnh.',
      'Data can close the gap ¦ Advantage is plausible only for special structure ¦ Always test classical kernels',
      'Dữ liệu có thể thu hẹp khoảng cách ¦ Lợi thế chỉ khả dĩ với cấu trúc đặc biệt ¦ Luôn thử kernel cổ điển',
      [[AX('2011.01938'), 'Huang et al.: Power of data in quantum machine learning', 'Read the abstract and the geometric difference.', 'Đọc tóm tắt và độ khác biệt hình học.'],
       ['https://www.nature.com/articles/s41567-021-01287-z', 'Liu, Arunachalam, Temme: rigorous quantum speed-up (Nature Physics)', 'Read the abstract.', 'Đọc tóm tắt.'],
       [YT('eSvib4kXkIk'), 'Huang: Power of data in QML (QML Meetup)', 'Watch the talk.', 'Xem buổi nói chuyện.']]],
  ]),

  C(4, ['Variational quantum circuits', 'Mạch lượng tử biến phân'], 'Mạch tham số hoá, hàm chi phí, vòng lặp lai và VQE.', [
    [['Parametrised quantum circuits and ansatz design', 'Mạch lượng tử tham số hoá và thiết kế ansatz'],
      'Build a layered ansatz ¦ Compare hardware-efficient and problem-inspired ansatzes',
      'Dựng ansatz nhiều lớp ¦ So ansatz hiệu quả phần cứng và ansatz theo bài toán',
      'A parametrised circuit U(theta) applies rotation gates with trainable angles interleaved with entanglers ¦ Hardware-efficient ansatzes (RealAmplitudes, EfficientSU2) use native gates and shallow depth ¦ Problem-inspired ansatzes encode structure of the task and often train better ¦ More layers increase expressivity but also noise and training difficulty ¦ The circuit plus measurement defines a function of theta.',
      'Mạch tham số hoá U(theta) áp các cổng quay với góc huấn luyện được xen kẽ cổng vướng víu ¦ Ansatz hiệu quả phần cứng (RealAmplitudes, EfficientSU2) dùng cổng gốc và độ sâu nông ¦ Ansatz theo bài toán mã hoá cấu trúc nhiệm vụ và thường huấn luyện tốt hơn ¦ Nhiều lớp hơn tăng biểu đạt nhưng cũng tăng nhiễu và khó huấn luyện ¦ Mạch cộng phép đo định nghĩa một hàm của theta.',
      'Ansatz = trainable rotations plus entanglers ¦ Depth trades expressivity for noise ¦ Structure helps trainability',
      'Ansatz = phép quay huấn luyện được cộng cổng vướng víu ¦ Độ sâu đánh đổi biểu đạt và nhiễu ¦ Cấu trúc giúp huấn luyện',
      [[AX('1906.07682'), 'Benedetti et al.: Parameterized quantum circuits as ML models', 'Read the sections on ansatz families.', 'Đọc các mục về họ ansatz.'],
       [AX('2012.09265'), 'Cerezo et al.: Variational Quantum Algorithms', 'Read the ansatz section.', 'Đọc mục ansatz.'],
       [YT('bVymBcvE7BA'), 'Quantum ML 20: Variational circuits and quantum simulation', 'Watch the introduction to variational circuits.', 'Xem phần giới thiệu mạch biến phân.']]],
    [['Cost functions and the hybrid optimisation loop', 'Hàm chi phí và vòng lặp tối ưu lai'],
      'Describe the quantum-classical loop ¦ Choose local or global cost functions',
      'Mô tả vòng lặp lượng tử-cổ điển ¦ Chọn hàm chi phí cục bộ hay toàn cục',
      'The quantum device evaluates a cost C(theta) = <psi(theta)|H|psi(theta)> from many shots, and a classical optimiser proposes new theta ¦ Gradient-free optimisers (COBYLA, SPSA) are noise-tolerant, gradient-based ones (Adam) are faster when gradients are available ¦ Local cost functions measuring few qubits train better than global ones ¦ Count shots: each cost estimate has statistical error 1 / sqrt(shots).',
      'Thiết bị lượng tử đánh giá chi phí C(theta) = <psi(theta)|H|psi(theta)> từ nhiều shot và bộ tối ưu cổ điển đề xuất theta mới ¦ Bộ tối ưu không dùng gradient (COBYLA, SPSA) chịu nhiễu tốt, bộ dùng gradient (Adam) nhanh hơn khi có gradient ¦ Hàm chi phí cục bộ đo ít qubit huấn luyện tốt hơn hàm toàn cục ¦ Tính shot: mỗi ước lượng chi phí có sai số thống kê 1 / sqrt(shot).',
      'Quantum evaluates, classical optimises ¦ Local costs train better ¦ Shot noise limits precision',
      'Lượng tử đánh giá, cổ điển tối ưu ¦ Chi phí cục bộ huấn luyện tốt hơn ¦ Nhiễu shot giới hạn độ chính xác',
      [[AX('2012.09265'), 'Cerezo et al.: Variational Quantum Algorithms', 'Read the cost function and optimiser sections.', 'Đọc các mục hàm chi phí và bộ tối ưu.'],
       [PL('tutorial_spsa'), 'PennyLane: optimisation using SPSA', 'Run the demo.', 'Chạy bản demo.'],
       ['https://www.nature.com/articles/s42254-021-00348-9', 'Cerezo et al. (Nature Reviews Physics)', 'Open the published review.', 'Mở bài tổng quan đã xuất bản.'],
       [AX('1509.04279'), 'McClean et al.: Theory of variational hybrid quantum-classical algorithms', 'Read the hybrid loop framework.', 'Đọc khung vòng lặp lai.']]],
    [['VQE as the template variational algorithm', 'VQE như thuật toán biến phân mẫu'],
      'Explain the variational principle ¦ Run VQE for a small Hamiltonian',
      'Giải thích nguyên lý biến phân ¦ Chạy VQE cho Hamiltonian nhỏ',
      'Variational principle: <psi|H|psi> is at least the ground-state energy E0 for any state ¦ VQE minimises the energy over a parametrised state to approximate E0 ¦ The Hamiltonian is split into Pauli terms measured separately ¦ Although VQE targets chemistry, the same loop (ansatz, measure, optimise) underlies quantum classifiers ¦ The first VQE experiment appeared in 2013.',
      'Nguyên lý biến phân: <psi|H|psi> không nhỏ hơn năng lượng nền E0 với mọi trạng thái ¦ VQE cực tiểu hoá năng lượng trên trạng thái tham số hoá để xấp xỉ E0 ¦ Hamiltonian được tách thành các số hạng Pauli đo riêng ¦ Dù VQE nhắm hoá học, cùng vòng lặp (ansatz, đo, tối ưu) nằm sau bộ phân loại lượng tử ¦ Thí nghiệm VQE đầu tiên xuất hiện năm 2013.',
      'Energy is bounded below by E0 ¦ Measure Pauli terms ¦ VQE shows the full variational loop',
      'Năng lượng bị chặn dưới bởi E0 ¦ Đo từng số hạng Pauli ¦ VQE thể hiện trọn vòng biến phân',
      [[AX('1304.3061'), 'Peruzzo et al.: A variational eigenvalue solver on a quantum processor', 'Read the abstract and method.', 'Đọc tóm tắt và phương pháp.'],
       [PL('tutorial_vqe'), 'PennyLane: a brief overview of VQE', 'Run the demo.', 'Chạy bản demo.'],
       [YT('DUq-0r-Prw0'), 'Qiskit: What is the Variational Quantum Eigensolver?', 'Watch the explainer.', 'Xem video giải thích.'],
       [YT('TUFovZsBcW4'), 'Qiskit: VQE Zero to Hero', 'Watch the coding walkthrough.', 'Xem hướng dẫn viết mã.']]],
    [['Expressibility and entangling capability of circuits', 'Khả năng biểu đạt và vướng víu của mạch'],
      'Measure expressibility of an ansatz ¦ Relate it to trainability',
      'Đo khả năng biểu đạt của ansatz ¦ Liên hệ với khả năng huấn luyện',
      'Expressibility measures how uniformly a circuit covers the space of states, compared with the Haar-random distribution ¦ Entangling capability measures the entanglement generated ¦ Highly expressive circuits are harder to train because gradients vanish ¦ Choose the least expressive circuit that fits the task ¦ Sim et al. rank common circuit templates by both measures.',
      'Biểu đạt đo mức mạch phủ đều không gian trạng thái, so với phân phối ngẫu nhiên Haar ¦ Khả năng vướng víu đo mức vướng víu sinh ra ¦ Mạch biểu đạt cao khó huấn luyện hơn vì gradient biến mất ¦ Chọn mạch ít biểu đạt nhất vẫn hợp nhiệm vụ ¦ Sim và cộng sự xếp hạng các mẫu mạch phổ biến theo cả hai độ đo.',
      'Expressibility compares against Haar random ¦ More expressive means harder to train ¦ Match capacity to the task',
      'Biểu đạt so với ngẫu nhiên Haar ¦ Biểu đạt hơn nghĩa là khó huấn luyện hơn ¦ Chọn dung lượng hợp nhiệm vụ',
      [[AX('1905.10876'), 'Sim et al.: Expressibility and entangling capability of parameterized circuits', 'Read the metrics definition.', 'Đọc định nghĩa các độ đo.'],
       [PL('tutorial_haar_measure'), 'PennyLane: understanding the Haar measure', 'Read the demo for background.', 'Đọc bản demo để lấy nền.'],
       [YT('1-IrbRR4rwM'), 'Qiskit Lecture 10.2: Capacity and power of QML models', 'Watch the capacity discussion.', 'Xem thảo luận về dung lượng.']]],
  ]),

  C(5, ['Training quantum models: gradients, barren plateaus and noise', 'Huấn luyện mô hình lượng tử: gradient, cao nguyên cằn cỗi và nhiễu'], 'Quy tắc parameter-shift, tự động đạo hàm, barren plateau, nhiễu và giảm thiểu lỗi.', [
    [['The parameter-shift rule', 'Quy tắc parameter-shift'],
      'Derive the parameter-shift gradient ¦ Compare it to finite differences',
      'Suy ra gradient parameter-shift ¦ So với sai phân hữu hạn',
      'For gates generated by Pauli operators, the exact derivative is d f / d theta = (f(theta + π/2) - f(theta - π/2)) / 2 ¦ It uses two extra circuit evaluations per parameter and works on real hardware ¦ Unlike finite differences, the shift is large, so it is robust to shot noise ¦ The cost scales with the number of parameters, which is why gradient estimation is expensive.',
      'Với cổng sinh bởi toán tử Pauli, đạo hàm chính xác là d f / d theta = (f(theta + π/2) - f(theta - π/2)) / 2 ¦ Cần hai lần chạy mạch thêm cho mỗi tham số và chạy được trên phần cứng thật ¦ Khác sai phân hữu hạn, bước dịch lớn nên bền với nhiễu shot ¦ Chi phí tăng theo số tham số, vì vậy ước lượng gradient đắt.',
      'Exact gradients from shifted circuits ¦ Two evaluations per parameter ¦ Works on hardware',
      'Gradient chính xác từ mạch dịch ¦ Hai lần chạy mỗi tham số ¦ Chạy được trên phần cứng',
      [[AX('1811.11184'), 'Schuld et al.: Evaluating analytic gradients on quantum hardware', 'Read the derivation.', 'Đọc phần suy ra.'],
       [YT('crgmwXBogx4'), 'PennyLane: parameter-shift rule derivation part 1', 'Watch the derivation.', 'Xem phần suy ra.'],
       [YT('TnFIW7cYLFU'), 'PennyLane: parameter-shift rule derivation part 2', 'Watch the continuation.', 'Xem phần tiếp.'],
       ['https://pennylane.ai/qml/glossary/parameter_shift', 'PennyLane glossary: parameter-shift', 'Read the summary.', 'Đọc phần tóm tắt.']]],
    [['Automatic differentiation and quantum natural gradient', 'Tự động đạo hàm và gradient tự nhiên lượng tử'],
      'Choose a differentiation method ¦ Explain quantum natural gradient',
      'Chọn phương pháp đạo hàm ¦ Giải thích gradient tự nhiên lượng tử',
      'On simulators, backpropagation gives all gradients in one pass but is not possible on hardware ¦ Frameworks choose between backprop, parameter-shift and adjoint methods ¦ Quantum natural gradient rescales the update by the quantum geometric tensor (Fubini-Study metric), following steepest descent in state space rather than parameter space ¦ It can converge in fewer steps at higher cost per step.',
      'Trên bộ mô phỏng, lan truyền ngược cho mọi gradient trong một lượt nhưng không làm được trên phần cứng ¦ Framework chọn giữa backprop, parameter-shift và phương pháp adjoint ¦ Gradient tự nhiên lượng tử đổi tỉ lệ bước theo tensor hình học lượng tử (độ đo Fubini-Study), đi theo hướng dốc nhất trong không gian trạng thái thay vì không gian tham số ¦ Có thể hội tụ ít bước hơn nhưng mỗi bước đắt hơn.',
      'Backprop only on simulators ¦ Parameter-shift on hardware ¦ Natural gradient uses state-space geometry',
      'Backprop chỉ trên bộ mô phỏng ¦ Parameter-shift trên phần cứng ¦ Gradient tự nhiên dùng hình học không gian trạng thái',
      [[PL('tutorial_backprop'), 'PennyLane: quantum gradients with backpropagation', 'Run the demo and compare timings.', 'Chạy demo và so thời gian.'],
       [PL('tutorial_quantum_natural_gradient'), 'PennyLane: quantum natural gradient', 'Run the demo.', 'Chạy bản demo.'],
       [AX('1909.02108'), 'Stokes et al.: Quantum Natural Gradient', 'Read the abstract.', 'Đọc tóm tắt.'],
       ['https://docs.pennylane.ai/en/stable/introduction/interfaces.html', 'PennyLane: gradients and training', 'Read the diff_method options.', 'Đọc các tuỳ chọn diff_method.']]],
    [['Barren plateaus and trainability', 'Cao nguyên cằn cỗi và khả năng huấn luyện'],
      'Explain why gradients vanish exponentially ¦ List mitigation strategies',
      'Giải thích vì sao gradient triệt tiêu theo cấp số mũ ¦ Liệt kê cách giảm nhẹ',
      'McClean et al. showed that for random deep circuits the variance of the gradient shrinks exponentially with the number of qubits: the landscape is flat ¦ Causes: very expressive circuits, global cost functions, entanglement and noise ¦ Mitigations: shallow or structured ansatzes, local costs, smart initialisation, layer-wise training ¦ Some work argues that circuits free of barren plateaus may be classically simulable.',
      'McClean và cộng sự chỉ ra rằng với mạch sâu ngẫu nhiên, phương sai của gradient giảm theo cấp số mũ theo số qubit: bề mặt phẳng ¦ Nguyên nhân: mạch biểu đạt rất cao, hàm chi phí toàn cục, vướng víu và nhiễu ¦ Giảm nhẹ: ansatz nông hoặc có cấu trúc, chi phí cục bộ, khởi tạo khéo, huấn luyện từng lớp ¦ Một số công trình cho rằng mạch không có cao nguyên cằn cỗi có thể mô phỏng được bằng máy cổ điển.',
      'Random deep circuits have flat landscapes ¦ Local costs and structure help ¦ Trainability and classical simulability may be linked',
      'Mạch sâu ngẫu nhiên có bề mặt phẳng ¦ Chi phí cục bộ và cấu trúc giúp ích ¦ Khả năng huấn luyện và mô phỏng cổ điển có thể liên quan',
      [[AX('1803.11173'), 'McClean et al.: Barren plateaus in QNN training landscapes', 'Read the main theorem.', 'Đọc định lý chính.'],
       [PL('tutorial_barren_plateaus'), 'PennyLane: barren plateaus', 'Reproduce the vanishing gradient experiment.', 'Tái hiện thí nghiệm gradient triệt tiêu.'],
       [YT('0ENQXz9tDww'), 'Qiskit Lecture 8.2: Barren plateaus and trainability', 'Watch the lecture.', 'Xem bài giảng.'],
       [AX('2312.09121'), 'Does provable absence of barren plateaus imply classical simulability?', 'Read the abstract.', 'Đọc tóm tắt.']]],
    [['Noise, shot cost and error mitigation', 'Nhiễu, chi phí shot và giảm thiểu lỗi'],
      'Describe how noise changes the landscape ¦ Apply zero-noise extrapolation',
      'Mô tả nhiễu thay đổi bề mặt thế nào ¦ Áp dụng ngoại suy nhiễu bằng không',
      'Hardware noise can itself flatten gradients (noise-induced barren plateaus) ¦ Statistical error needs O(1 / ε²) shots for precision ε, so every gradient is costly ¦ Error mitigation reduces bias without full error correction: zero-noise extrapolation, probabilistic error cancellation, readout correction ¦ Mitigation increases sampling overhead ¦ Simulate with a noise model before touching hardware.',
      'Nhiễu phần cứng tự nó có thể làm phẳng gradient (cao nguyên cằn cỗi do nhiễu) ¦ Sai số thống kê cần O(1 / ε²) shot để đạt độ chính xác ε nên mỗi gradient tốn kém ¦ Giảm thiểu lỗi giảm độ lệch mà không cần sửa lỗi đầy đủ: ngoại suy nhiễu bằng không, triệt lỗi xác suất, hiệu chỉnh đọc ra ¦ Giảm thiểu làm tăng chi phí lấy mẫu ¦ Mô phỏng với mô hình nhiễu trước khi đụng phần cứng.',
      'Noise can flatten training ¦ Shots scale as 1 over epsilon squared ¦ Mitigation costs more samples',
      'Nhiễu có thể làm phẳng huấn luyện ¦ Shot tăng theo 1 trên epsilon bình phương ¦ Giảm thiểu tốn thêm mẫu',
      [[AX('2007.14384'), 'Wang et al.: Noise-induced barren plateaus', 'Read the abstract.', 'Đọc tóm tắt.'],
       [PL('tutorial_error_mitigation'), 'PennyLane: error mitigation with Mitiq', 'Run the demo.', 'Chạy bản demo.'],
       [PL('tutorial_noisy_circuits'), 'PennyLane: noisy circuits', 'Add a noise model to a simulation.', 'Thêm mô hình nhiễu vào mô phỏng.'],
       ['https://www.nature.com/articles/s41586-023-06096-3', 'Kim et al.: Evidence for the utility of quantum computing before fault tolerance', 'Read how mitigation was used.', 'Đọc cách dùng giảm thiểu lỗi.']]],
  ]),

  C(6, ['Quantum neural networks and hybrid models', 'Mạng nơ-ron lượng tử và mô hình lai'], 'Bộ phân loại mạch, QNN, mạng lai với PyTorch, QCNN và chuyển giao học.', [
    [['Variational quantum classifiers', 'Bộ phân loại lượng tử biến phân'],
      'Build a circuit-centric classifier ¦ Train it on a small dataset',
      'Dựng bộ phân loại lấy mạch làm trung tâm ¦ Huấn luyện trên dữ liệu nhỏ',
      'A variational classifier encodes x, applies a trainable ansatz and reads a measurement as the prediction (expectation of Z on one qubit) ¦ The loss compares the output with labels ¦ Circuit-centric design uses few qubits and shallow depth ¦ Compare with a small classical model, e.g. logistic regression, on the same split ¦ Qiskit calls this VQC.',
      'Bộ phân loại biến phân mã hoá x, áp ansatz huấn luyện được và đọc phép đo làm dự đoán (kỳ vọng Z trên một qubit) ¦ Hàm mất mát so đầu ra với nhãn ¦ Thiết kế lấy mạch làm trung tâm dùng ít qubit và độ sâu nông ¦ So với mô hình cổ điển nhỏ, ví dụ hồi quy logistic, trên cùng cách chia ¦ Qiskit gọi đây là VQC.',
      'Encode, rotate, measure ¦ Few qubits and shallow depth ¦ Always compare with a classical baseline',
      'Mã hoá, quay, đo ¦ Ít qubit và nông ¦ Luôn so với mốc cổ điển',
      [[AX('1804.00633'), 'Schuld et al.: Circuit-centric quantum classifiers', 'Read the architecture description.', 'Đọc mô tả kiến trúc.'],
       [PL('tutorial_variational_classifier'), 'PennyLane: variational classifier', 'Run the demo.', 'Chạy bản demo.'],
       [YT('-sxlXNz7ZxU'), 'Qiskit Lecture 5.1: Building a quantum classifier', 'Watch the build.', 'Xem phần xây dựng.'],
       [YT('m6EzmYsEOiI'), 'Qiskit Lecture 6.1: From variational classifiers to linear classifiers', 'Watch the link to linear models.', 'Xem liên hệ với mô hình tuyến tính.']]],
    [['Quantum neural networks: Sampler and Estimator based QNNs', 'Mạng nơ-ron lượng tử: QNN dựa trên Sampler và Estimator'],
      'Distinguish Estimator and Sampler QNNs ¦ Train a QNN regressor',
      'Phân biệt QNN dựa Estimator và Sampler ¦ Huấn luyện bộ hồi quy QNN',
      'A QNN combines a feature map, an ansatz and an output: an expectation value (Estimator-style, good for regression) or a probability distribution over bitstrings (Sampler-style, good for classification) ¦ Weights are the ansatz parameters ¦ Gradients are computed automatically via parameter-shift ¦ Early quantum perceptron and feedforward ideas appeared in 2014-2018 ¦ Treat the name QNN with care: these are parametrised circuits, not literal neurons.',
      'QNN kết hợp bản đồ đặc trưng, ansatz và đầu ra: giá trị kỳ vọng (kiểu Estimator, hợp hồi quy) hoặc phân phối xác suất trên chuỗi bit (kiểu Sampler, hợp phân loại) ¦ Trọng số là tham số ansatz ¦ Gradient tính tự động qua parameter-shift ¦ Ý tưởng perceptron và truyền thẳng lượng tử xuất hiện giai đoạn 2014-2018 ¦ Dùng tên QNN thận trọng: đây là mạch tham số hoá, không phải nơ-ron theo nghĩa đen.',
      'Estimator for expectations, Sampler for distributions ¦ Weights are circuit parameters ¦ QNN is a naming convention',
      'Estimator cho kỳ vọng, Sampler cho phân phối ¦ Trọng số là tham số mạch ¦ QNN là quy ước đặt tên',
      [[AX('1802.06002'), 'Farhi and Neven: Classification with QNNs on near-term processors', 'Read the architecture and training.', 'Đọc kiến trúc và huấn luyện.'],
       [AX('1612.01045'), 'Wan et al.: Quantum generalisation of feedforward neural networks', 'Read the abstract.', 'Đọc tóm tắt.'],
       ['https://github.com/qiskit-community/qiskit-machine-learning', 'Qiskit Machine Learning', 'Read the README on neural networks.', 'Đọc README về mạng nơ-ron.'],
       [YT('lkmehsypdag'), 'Simons Institute: Quantum neural networks', 'Watch the talk.', 'Xem buổi nói chuyện.']]],
    [['Hybrid quantum-classical networks with PyTorch', 'Mạng lai lượng tử-cổ điển với PyTorch'],
      'Wrap a circuit as a PyTorch layer ¦ Use transfer learning with a quantum head',
      'Bọc mạch thành lớp PyTorch ¦ Dùng chuyển giao học với đầu lượng tử',
      'A quantum node can be a layer inside a PyTorch module: classical layers produce features, the quantum layer processes them, a classical layer reads out ¦ Autograd sends gradients through the circuit ¦ Transfer learning: a pretrained classical network extracts features and a small quantum circuit classifies them ¦ Keep the quantum part small, since simulation of larger circuits is expensive ¦ Compare against the same network with a classical head.',
      'Nút lượng tử có thể là một lớp trong module PyTorch: lớp cổ điển tạo đặc trưng, lớp lượng tử xử lý, lớp cổ điển đọc ra ¦ Autograd gửi gradient qua mạch ¦ Chuyển giao học: mạng cổ điển tiền huấn luyện rút đặc trưng và mạch lượng tử nhỏ phân loại ¦ Giữ phần lượng tử nhỏ vì mô phỏng mạch lớn đắt ¦ So với cùng mạng có đầu cổ điển.',
      'Quantum layers fit inside PyTorch ¦ Transfer learning keeps circuits small ¦ Compare with a classical head',
      'Lớp lượng tử nằm trong PyTorch ¦ Chuyển giao học giữ mạch nhỏ ¦ So với đầu cổ điển',
      [[PL('tutorial_qnn_module_torch'), 'PennyLane: quantum nodes into Torch layers', 'Run the demo.', 'Chạy bản demo.'],
       [PL('tutorial_quantum_transfer_learning'), 'PennyLane: quantum transfer learning', 'Run the demo.', 'Chạy bản demo.'],
       [AX('1912.08278'), 'Mari et al.: Transfer learning in hybrid classical-quantum networks', 'Read the abstract.', 'Đọc tóm tắt.'],
       ['https://pytorch.org/tutorials/beginner/basics/buildmodel_tutorial.html', 'PyTorch: build the neural network', 'Review nn.Module.', 'Ôn nn.Module.']]],
    [['Convolutional and structured quantum models', 'Mô hình lượng tử tích chập và có cấu trúc'],
      'Describe the QCNN layout ¦ Explain why structure aids trainability',
      'Mô tả bố cục QCNN ¦ Giải thích vì sao cấu trúc hỗ trợ huấn luyện',
      'A quantum convolutional neural network alternates convolution layers (translation-invariant two-qubit gates) with pooling layers that reduce the number of qubits ¦ Depth is logarithmic in the input size, so QCNNs avoid barren plateaus ¦ Quanvolutional layers apply small random quantum circuits to image patches as feature extractors ¦ Tensor-network circuits give another structured family.',
      'Mạng nơ-ron tích chập lượng tử xen lớp tích chập (cổng hai qubit bất biến tịnh tiến) với lớp gộp giảm số qubit ¦ Độ sâu cỡ logarit theo kích thước đầu vào nên QCNN tránh được cao nguyên cằn cỗi ¦ Lớp quanvolution áp mạch lượng tử ngẫu nhiên nhỏ lên mảnh ảnh làm bộ rút đặc trưng ¦ Mạch mạng tensor là một họ có cấu trúc khác.',
      'Conv and pooling reduce qubits ¦ Log depth helps trainability ¦ Structure matches data symmetry',
      'Tích chập và gộp giảm qubit ¦ Độ sâu logarit giúp huấn luyện ¦ Cấu trúc khớp đối xứng dữ liệu',
      [[AX('1810.03787'), 'Cong, Choi, Lukin: Quantum Convolutional Neural Networks', 'Read the architecture section.', 'Đọc mục kiến trúc.'],
       [PL('tutorial_quanvolution'), 'PennyLane: quanvolutional neural networks', 'Run the demo.', 'Chạy bản demo.'],
       [PL('tutorial_tn_circuits'), 'PennyLane: tensor-network quantum circuits', 'Read the demo.', 'Đọc bản demo.']]],
  ]),

  C(7, ['Quantum algorithms for linear algebra and learning', 'Thuật toán lượng tử cho đại số tuyến tính và học máy'], 'HHL, qPCA, qSVM, ước lượng biên độ và phi lượng tử hoá.', [
    [['Quantum phase estimation and the HHL linear-systems algorithm', 'Ước lượng pha lượng tử và thuật toán giải hệ tuyến tính HHL'],
      'State what HHL computes ¦ List its conditions',
      'Phát biểu HHL tính gì ¦ Liệt kê điều kiện',
      'HHL prepares a state proportional to the solution x of Ax = b using phase estimation of e^(iA t), controlled rotations on eigenvalues and uncomputation ¦ Runtime is polylogarithmic in the dimension N but depends on the condition number and sparsity, and the output is a quantum state, not the vector ¦ Reading out all entries would cost N, so HHL answers questions about x (expectation values) ¦ Loading b and reading results are the main caveats.',
      'HHL chuẩn bị trạng thái tỉ lệ với nghiệm x của Ax = b bằng ước lượng pha của e^(iA t), phép quay điều khiển theo trị riêng và hoàn tác ¦ Thời gian chạy đa logarit theo kích thước N nhưng phụ thuộc số điều kiện và độ thưa, đầu ra là trạng thái lượng tử chứ không phải vector ¦ Đọc mọi phần tử tốn N nên HHL trả lời câu hỏi về x (giá trị kỳ vọng) ¦ Nạp b và đọc kết quả là các lưu ý chính.',
      'HHL outputs a quantum state ¦ Speedup depends on condition number and sparsity ¦ Input and output are caveats',
      'HHL xuất trạng thái lượng tử ¦ Tăng tốc phụ thuộc số điều kiện và độ thưa ¦ Đầu vào và đầu ra là lưu ý',
      [[AX('0811.3171'), 'Harrow, Hassidim, Lloyd: Quantum algorithm for linear systems of equations', 'Read the abstract and main result.', 'Đọc tóm tắt và kết quả chính.'],
       [AX('1802.08227'), 'Dervovic et al.: Quantum linear systems algorithms, a primer', 'Read the overview of assumptions.', 'Đọc tổng quan các giả định.'],
       [YT('hQpdPM-6wtU'), 'Quantum ML 37: Overview of the HHL algorithm', 'Watch the overview.', 'Xem tổng quan.'],
       [PL('tutorial_qpe'), 'PennyLane: intro to quantum phase estimation', 'Read the demo.', 'Đọc bản demo.']]],
    [['Quantum PCA, quantum SVM and Lloyd-style algorithms', 'qPCA, SVM lượng tử và thuật toán kiểu Lloyd'],
      'Describe the qPCA idea ¦ Explain least-squares quantum SVM',
      'Mô tả ý tưởng qPCA ¦ Giải thích SVM lượng tử bình phương tối thiểu',
      'Quantum PCA uses density matrix exponentiation to extract the principal eigenvectors of a covariance matrix from copies of a state ¦ Quantum SVM solves the least-squares SVM linear system with HHL-style methods ¦ Quantum clustering and nearest-centroid methods use distance estimation by the swap test ¦ All assume efficient state preparation (QRAM), the same caveat as HHL.',
      'qPCA dùng lũy thừa ma trận mật độ để rút các vector riêng chính của ma trận hiệp phương sai từ nhiều bản sao trạng thái ¦ SVM lượng tử giải hệ tuyến tính SVM bình phương tối thiểu bằng phương pháp kiểu HHL ¦ Gom cụm lượng tử và phương pháp tâm gần nhất dùng ước lượng khoảng cách bằng swap test ¦ Tất cả giả định chuẩn bị trạng thái hiệu quả (QRAM), cùng lưu ý với HHL.',
      'Density matrix exponentiation powers qPCA ¦ qSVM reduces to a linear system ¦ All rely on efficient data loading',
      'Lũy thừa ma trận mật độ là nền qPCA ¦ qSVM quy về hệ tuyến tính ¦ Tất cả cần nạp dữ liệu hiệu quả',
      [[AX('1307.0401'), 'Lloyd, Mohseni, Rebentrost: Quantum principal component analysis', 'Read the abstract.', 'Đọc tóm tắt.'],
       [AX('1307.0471'), 'Rebentrost et al.: Quantum support vector machine for big data classification', 'Read the abstract.', 'Đọc tóm tắt.'],
       [AX('1307.0411'), 'Lloyd et al.: Quantum algorithms for supervised and unsupervised learning', 'Read the abstract.', 'Đọc tóm tắt.']]],
    [['Amplitude estimation, Grover-style speedups and quantum sampling', 'Ước lượng biên độ, tăng tốc kiểu Grover và lấy mẫu lượng tử'],
      'Describe quadratic speedups ¦ Name uses in learning',
      'Mô tả tăng tốc bậc hai ¦ Kể tên ứng dụng trong học máy',
      'Grover search finds a marked item in O(sqrt(N)) queries, a quadratic speedup ¦ Amplitude estimation estimates a probability to precision ε in O(1 / ε) runs instead of O(1 / ε²) for classical sampling ¦ These give quadratic improvements for Monte Carlo, minimum finding and some training subroutines ¦ Quadratic speedups are modest and can be erased by hardware overhead ¦ Recall Grover and QFT from QTC211.',
      'Tìm kiếm Grover tìm mục được đánh dấu trong O(sqrt(N)) truy vấn, tăng tốc bậc hai ¦ Ước lượng biên độ ước lượng xác suất với độ chính xác ε trong O(1 / ε) lần chạy thay vì O(1 / ε²) của lấy mẫu cổ điển ¦ Chúng cho cải thiện bậc hai cho Monte Carlo, tìm cực tiểu và một số thủ tục huấn luyện ¦ Tăng tốc bậc hai khiêm tốn và có thể bị chi phí phần cứng xoá ¦ Nhớ lại Grover và QFT từ QTC211.',
      'Quadratic speedups are modest ¦ Amplitude estimation beats sampling ¦ Overhead can erase small gains',
      'Tăng tốc bậc hai khiêm tốn ¦ Ước lượng biên độ hơn lấy mẫu ¦ Chi phí phụ có thể xoá lợi nhỏ',
      [[PL('tutorial_grovers_algorithm'), "PennyLane: Grover's algorithm", 'Read the demo.', 'Đọc bản demo.'],
       [PL('tutorial_qft'), 'PennyLane: intro to the quantum Fourier transform', 'Review the QFT.', 'Ôn QFT.'],
       ['https://quantum.country/search', 'Quantum Country: how the quantum search algorithm works', 'Read the essay.', 'Đọc bài luận.']]],
    [['Dequantization: quantum-inspired classical algorithms', 'Phi lượng tử hoá: thuật toán cổ điển lấy cảm hứng lượng tử'],
      'Explain Tang result ¦ Judge claimed exponential speedups',
      'Giải thích kết quả của Tang ¦ Đánh giá các tuyên bố tăng tốc mũ',
      'Ewin Tang showed that the quantum recommendation-system algorithm can be matched by a classical algorithm with comparable sampling access to the data, removing the exponential speedup ¦ Similar dequantization results followed for qPCA, low-rank regression and some other tasks ¦ Lesson: speedups depend on the access model, so compare quantum algorithms with the best classical algorithm given equal data access ¦ Quantum advantage claims need careful baselines.',
      'Ewin Tang chỉ ra rằng thuật toán gợi ý lượng tử có thể được thuật toán cổ điển với truy cập lấy mẫu tương đương đối sánh, xoá tăng tốc mũ ¦ Các kết quả phi lượng tử hoá tương tự tiếp theo cho qPCA, hồi quy hạng thấp và vài bài toán khác ¦ Bài học: tăng tốc phụ thuộc mô hình truy cập, nên so thuật toán lượng tử với thuật toán cổ điển tốt nhất khi truy cập dữ liệu như nhau ¦ Tuyên bố lợi thế cần mốc so sánh cẩn thận.',
      'Access model decides the speedup ¦ Dequantization removed exponential claims ¦ Always use the best classical baseline',
      'Mô hình truy cập quyết định tăng tốc ¦ Phi lượng tử hoá xoá tuyên bố mũ ¦ Luôn dùng mốc cổ điển tốt nhất',
      [[AX('1807.04271'), 'Tang: A quantum-inspired classical algorithm for recommendation systems', 'Read the abstract and intro.', 'Đọc tóm tắt và phần mở đầu.'],
       [YT('j4k6aVihQXE'), 'Simons Institute: Classical algorithm framework for dequantizing QML', 'Watch the talk.', 'Xem buổi nói chuyện.'],
       [YT('yGlg2VrNPds'), 'McClean: Dequantization and quantum advantage in learning from experiments', 'Watch the talk.', 'Xem buổi nói chuyện.']]],
  ]),

  C(8, ['Quantum generative and unsupervised models', 'Mô hình sinh và không giám sát lượng tử'], 'Born machine, QGAN, autoencoder lượng tử và gom cụm.', [
    [['Quantum circuit Born machines and generative modelling', 'Born machine mạch lượng tử và mô hình sinh'],
      'Explain sampling as generation ¦ Train a circuit to match a distribution',
      'Giải thích lấy mẫu như sinh dữ liệu ¦ Huấn luyện mạch khớp một phân phối',
      'A parametrised circuit prepares a state whose measurement outcomes follow the Born rule p(x) = |<x|psi(theta)>|² ¦ Training minimises a distance (KL divergence, maximum mean discrepancy) between p and the data distribution ¦ Sampling is natural for quantum circuits but computing p(x) exactly is hard, so losses use samples ¦ Compare with classical generative baselines.',
      'Mạch tham số hoá chuẩn bị trạng thái có kết quả đo theo quy tắc Born p(x) = |<x|psi(theta)>|² ¦ Huấn luyện cực tiểu hoá khoảng cách (phân kỳ KL, maximum mean discrepancy) giữa p và phân phối dữ liệu ¦ Lấy mẫu là tự nhiên với mạch lượng tử nhưng tính p(x) chính xác khó nên hàm mất mát dùng mẫu ¦ So với mốc sinh cổ điển.',
      'Measurement samples are the generator ¦ Losses must work from samples ¦ Compare with classical models',
      'Mẫu đo là bộ sinh ¦ Hàm mất mát phải dựa trên mẫu ¦ So với mô hình cổ điển',
      [[AX('1906.07682'), 'Benedetti et al.: Parameterized quantum circuits as ML models', 'Read the generative models section.', 'Đọc mục mô hình sinh.'],
       [AX('1804.09139'), 'Lloyd and Weedbrook: Quantum generative adversarial learning', 'Read the abstract for the generative setting.', 'Đọc tóm tắt cho bối cảnh mô hình sinh.']]],
    [['Quantum generative adversarial networks', 'Mạng sinh đối kháng lượng tử'],
      'Describe the generator-discriminator game ¦ Name the QGAN variants',
      'Mô tả trò chơi bộ sinh-bộ phân biệt ¦ Kể tên các biến thể QGAN',
      'In a GAN a generator tries to fool a discriminator ¦ Quantum variants replace the generator, the discriminator or both with parametrised circuits ¦ Lloyd and Weedbrook proposed the quantum adversarial framework, and Zoufal et al. use a quantum generator to load probability distributions into a quantum state efficiently ¦ Training GANs is unstable and quantum noise adds to the difficulty.',
      'Trong GAN bộ sinh cố đánh lừa bộ phân biệt ¦ Biến thể lượng tử thay bộ sinh, bộ phân biệt hoặc cả hai bằng mạch tham số hoá ¦ Lloyd và Weedbrook đề xuất khung đối kháng lượng tử, còn Zoufal và cộng sự dùng bộ sinh lượng tử để nạp phân phối xác suất vào trạng thái lượng tử hiệu quả ¦ Huấn luyện GAN không ổn định và nhiễu lượng tử làm khó hơn.',
      'Generator versus discriminator ¦ Quantum parts can be either player ¦ Training is delicate',
      'Bộ sinh đối đầu bộ phân biệt ¦ Phần lượng tử có thể là bên nào cũng được ¦ Huấn luyện mong manh',
      [[AX('1804.09139'), 'Lloyd and Weedbrook: Quantum generative adversarial learning', 'Read the abstract.', 'Đọc tóm tắt.'],
       [AX('1904.00043'), 'Zoufal et al.: Quantum GANs for learning and loading random distributions', 'Read the abstract and method.', 'Đọc tóm tắt và phương pháp.'],
       [PL('tutorial_quantum_gans'), 'PennyLane: quantum GANs', 'Run the demo.', 'Chạy bản demo.']]],
    [['Quantum clustering, autoencoders and unsupervised learning', 'Gom cụm, autoencoder và học không giám sát lượng tử'],
      'Describe clustering via QAOA ¦ Explain quantum autoencoders',
      'Mô tả gom cụm qua QAOA ¦ Giải thích autoencoder lượng tử',
      'Clustering can be written as a MaxCut problem and solved with QAOA on a quantum computer ¦ A quantum autoencoder compresses a state into fewer qubits, discarding the trash qubits ¦ Hybrid quantum-classical clustering uses distance estimation by swap test ¦ Classical unsupervised baselines (k-means, PCA) must be reported alongside.',
      'Gom cụm viết được thành bài toán MaxCut và giải bằng QAOA trên máy tính lượng tử ¦ Autoencoder lượng tử nén trạng thái vào ít qubit hơn, bỏ các qubit rác ¦ Gom cụm lai lượng tử-cổ điển dùng ước lượng khoảng cách bằng swap test ¦ Phải báo cáo mốc không giám sát cổ điển (k-means, PCA) bên cạnh.',
      'Clustering maps to MaxCut ¦ Autoencoders compress states ¦ Report classical baselines',
      'Gom cụm ánh xạ sang MaxCut ¦ Autoencoder nén trạng thái ¦ Báo cáo mốc cổ điển',
      [[AX('1712.05771'), 'Otterbach et al.: Unsupervised ML on a hybrid quantum computer', 'Read the abstract on clustering with QAOA.', 'Đọc tóm tắt về gom cụm bằng QAOA.'],
       [AX('1307.0411'), 'Lloyd et al.: Quantum algorithms for supervised and unsupervised learning', 'Read the clustering part.', 'Đọc phần gom cụm.'],
       ['https://scikit-learn.org/stable/modules/clustering.html', 'scikit-learn: clustering', 'Use as the classical baseline reference.', 'Dùng làm tham chiếu mốc cổ điển.']]],
  ]),

  C(9, ['Quantum optimisation: QUBO, QAOA and annealing', 'Tối ưu lượng tử: QUBO, QAOA và ủ lượng tử'], 'Công thức QUBO/Ising, QAOA và ủ lượng tử.', [
    [['QUBO and Ising formulations of optimisation problems', 'Công thức QUBO và Ising cho bài toán tối ưu'],
      'Write MaxCut as a QUBO ¦ Convert between QUBO and Ising',
      'Viết MaxCut dưới dạng QUBO ¦ Chuyển giữa QUBO và Ising',
      'QUBO minimises x^T Q x over binary variables ¦ Substituting x = (1 - s) / 2 maps it to an Ising Hamiltonian over spins s = ±1 ¦ MaxCut: maximise the number of edges between two groups, a QUBO with one term per edge ¦ Constraints become penalty terms ¦ Many problems in logistics, finance and ML (clustering, feature selection) can be cast as QUBO.',
      'QUBO cực tiểu hoá x^T Q x trên biến nhị phân ¦ Thế x = (1 - s) / 2 đưa nó về Hamiltonian Ising trên spin s = ±1 ¦ MaxCut: cực đại số cạnh giữa hai nhóm, QUBO với một số hạng cho mỗi cạnh ¦ Ràng buộc thành số hạng phạt ¦ Nhiều bài toán logistics, tài chính và ML (gom cụm, chọn đặc trưng) viết được dưới dạng QUBO.',
      'QUBO equals Ising ¦ Penalties encode constraints ¦ Many ML tasks map to QUBO',
      'QUBO tương đương Ising ¦ Số hạng phạt mã hoá ràng buộc ¦ Nhiều bài ML ánh xạ sang QUBO',
      [['https://qiskit-community.github.io/qiskit-optimization/tutorials/01_quadratic_program.html', 'Qiskit Optimization: quadratic programs', 'Read the tutorial.', 'Đọc hướng dẫn.'],
       ['https://qiskit-community.github.io/qiskit-optimization/tutorials/06_examples_max_cut_and_tsp.html', 'Qiskit Optimization: Max-Cut and TSP', 'Run the Max-Cut example.', 'Chạy ví dụ Max-Cut.'],
       [AX('1411.4028'), 'Farhi et al.: A Quantum Approximate Optimization Algorithm', 'Read the MaxCut application.', 'Đọc ứng dụng MaxCut.']]],
    [['The Quantum Approximate Optimization Algorithm (QAOA)', 'Thuật toán tối ưu xấp xỉ lượng tử (QAOA)'],
      'Build a depth-p QAOA circuit ¦ Tune its angles',
      'Dựng mạch QAOA độ sâu p ¦ Chỉnh các góc của nó',
      'QAOA alternates a cost unitary exp(-iγC) and a mixer exp(-iβB) for p layers, starting from the uniform superposition ¦ The 2p angles are optimised classically to maximise the expected cost ¦ Larger p improves the approximation ratio but deepens the circuit ¦ QAOA is a variational algorithm, so barren plateaus and noise apply ¦ Whether it beats classical solvers remains open.',
      'QAOA xen kẽ unitary chi phí exp(-iγC) và unitary trộn exp(-iβB) qua p lớp, bắt đầu từ chồng chập đều ¦ 2p góc được tối ưu cổ điển để cực đại chi phí kỳ vọng ¦ p lớn hơn cải thiện tỉ số xấp xỉ nhưng làm mạch sâu hơn ¦ QAOA là thuật toán biến phân nên cao nguyên cằn cỗi và nhiễu đều áp dụng ¦ Việc nó có hơn bộ giải cổ điển hay không vẫn bỏ ngỏ.',
      'Cost and mixer layers alternate ¦ Angles are tuned classically ¦ Advantage is unproven',
      'Lớp chi phí và lớp trộn xen kẽ ¦ Góc được chỉnh bằng cổ điển ¦ Lợi thế chưa chứng minh',
      [[AX('1411.4028'), 'Farhi, Goldstone, Gutmann: QAOA', 'Read the algorithm definition.', 'Đọc định nghĩa thuật toán.'],
       [PL('tutorial_qaoa_intro'), 'PennyLane: intro to QAOA', 'Run the demo.', 'Chạy bản demo.'],
       [PL('tutorial_qaoa_maxcut'), 'PennyLane: QAOA for MaxCut', 'Run the demo.', 'Chạy bản demo.'],
       [YT('YpLzSQPrgSc'), 'Qiskit Lecture 5.2: Intro to QAOA and applications', 'Watch the lecture.', 'Xem bài giảng.']]],
    [['Quantum annealing and D-Wave', 'Ủ lượng tử và D-Wave'],
      'Contrast annealing with gate-model QAOA ¦ Submit a QUBO to an annealer in principle',
      'Đối chiếu ủ lượng tử với QAOA mô hình cổng ¦ Nguyên lý gửi QUBO lên máy ủ',
      'Quantum annealing evolves slowly from an easy Hamiltonian to the problem Hamiltonian, hoping to stay near the ground state ¦ D-Wave systems are special-purpose annealers with thousands of qubits and limited connectivity, so problems are embedded onto the hardware graph ¦ Inputs are QUBO or Ising models ¦ Performance relative to classical heuristics is debated ¦ Gate-model QAOA is the digital analogue.',
      'Ủ lượng tử tiến hoá chậm từ Hamiltonian dễ sang Hamiltonian bài toán, hy vọng ở gần trạng thái nền ¦ Hệ D-Wave là máy ủ chuyên dụng với hàng nghìn qubit và kết nối hạn chế nên bài toán được nhúng lên đồ thị phần cứng ¦ Đầu vào là mô hình QUBO hoặc Ising ¦ Hiệu năng so với heuristic cổ điển còn tranh luận ¦ QAOA mô hình cổng là bản tương tự số.',
      'Annealing is analog and special-purpose ¦ Embedding onto hardware graphs is required ¦ Compare with classical heuristics',
      'Ủ là tương tự và chuyên dụng ¦ Cần nhúng lên đồ thị phần cứng ¦ So với heuristic cổ điển',
      [['https://docs.dwavequantum.com/en/latest/index.html', 'D-Wave documentation', 'Read the introduction to annealing and Ocean.', 'Đọc phần giới thiệu ủ và Ocean.'],
       [YT('zvfkXjzzYOo'), 'D-Wave: What is quantum annealing?', 'Watch the explainer.', 'Xem video giải thích.'],
       ['https://docs.dwavequantum.com/en/latest/ocean/index.html', 'D-Wave Ocean SDK', 'Skim the SDK overview.', 'Lướt tổng quan SDK.']]],
  ]),

  C(10, ['Evaluation, advantage and capstone', 'Đánh giá, lợi thế lượng tử và đồ án'], 'Chuẩn so sánh, tổng quát hoá, phần cứng và đồ án cuối môn.', [
    [['Benchmarking QML against classical baselines', 'So chuẩn QML với mốc cổ điển'],
      'Design a fair benchmark ¦ Recognise common pitfalls',
      'Thiết kế phép so chuẩn công bằng ¦ Nhận ra cạm bẫy phổ biến',
      'A 2024 large-scale study found that out-of-the-box classical models often match or beat quantum models on small classification tasks, and removing entanglement frequently does not hurt ¦ Fair benchmarks tune hyperparameters of both sides, use several datasets and report variance across seeds ¦ Avoid tiny toy data and untuned baselines ¦ Report cost: circuit evaluations, shots, wall-clock time.',
      'Một nghiên cứu quy mô lớn năm 2024 thấy mô hình cổ điển dùng sẵn thường ngang hoặc hơn mô hình lượng tử trên các bài phân loại nhỏ, và bỏ vướng víu thường không gây hại ¦ Phép so chuẩn công bằng chỉnh siêu tham số cả hai phía, dùng nhiều bộ dữ liệu và báo cáo phương sai qua các seed ¦ Tránh dữ liệu đồ chơi quá nhỏ và mốc chưa chỉnh ¦ Báo cáo chi phí: số lần chạy mạch, số shot, thời gian thực.',
      'Tune baselines properly ¦ Use several datasets and seeds ¦ Report costs',
      'Chỉnh mốc cho đúng ¦ Dùng nhiều dữ liệu và seed ¦ Báo cáo chi phí',
      [[AX('2403.07059'), 'Bowles et al.: Better than classical? Benchmarking quantum ML models', 'Read the abstract and conclusions.', 'Đọc tóm tắt và kết luận.'],
       [AX('2312.09121'), 'Does provable absence of barren plateaus imply classical simulability?', 'Read the implications.', 'Đọc các hệ quả.'],
       [PL('tutorial_mitigation_advantage'), 'PennyLane: Is quantum computing useful before fault tolerance?', 'Read the discussion.', 'Đọc phần thảo luận.']]],
    [['Generalisation and learning theory for quantum models', 'Tổng quát hoá và lý thuyết học cho mô hình lượng tử'],
      'State generalisation bounds ¦ Explain learning from few data',
      'Phát biểu cận tổng quát hoá ¦ Giải thích học từ ít dữ liệu',
      'Caro et al. prove that the generalisation gap of a quantum model grows with the number of trainable gates, so few training points can suffice if the circuit has few parameters ¦ Capacity measures (Fourier spectrum, effective dimension) relate to overfitting ¦ Quantum advantage in learning from experiments shows provable gaps when a quantum memory is available ¦ Theory guides model choice but practical datasets differ from the assumptions.',
      'Caro và cộng sự chứng minh rằng khoảng cách tổng quát hoá của mô hình lượng tử tăng theo số cổng huấn luyện được, nên ít điểm huấn luyện có thể đủ nếu mạch ít tham số ¦ Các độ đo dung lượng (phổ Fourier, chiều hiệu dụng) liên quan quá khớp ¦ Lợi thế lượng tử khi học từ thí nghiệm cho khoảng cách chứng minh được khi có bộ nhớ lượng tử ¦ Lý thuyết dẫn lối chọn mô hình nhưng dữ liệu thực khác giả định.',
      'Fewer parameters mean better generalisation bounds ¦ Capacity relates to overfitting ¦ Theory and practice differ',
      'Ít tham số cho cận tổng quát hoá tốt hơn ¦ Dung lượng liên quan quá khớp ¦ Lý thuyết và thực hành khác nhau',
      [[AX('2111.05292'), 'Caro et al.: Generalization in QML from few training data', 'Read the abstract and main bound.', 'Đọc tóm tắt và cận chính.'],
       [PL('tutorial_learning_few_data'), 'PennyLane: generalization in QML from few training data', 'Run the demo.', 'Chạy bản demo.'],
       [AX('2112.00778'), 'Huang et al.: Quantum advantage in learning from experiments', 'Read the abstract.', 'Đọc tóm tắt.'],
       [YT('1-IrbRR4rwM'), 'Qiskit Lecture 10.2: Capacity and power of QML models', 'Watch the lecture.', 'Xem bài giảng.']]],
    [['Hardware reality: noise, scaling and the road to fault tolerance', 'Thực tế phần cứng: nhiễu, mở rộng và con đường tới chịu lỗi'],
      'Summarise hardware platforms ¦ Relate error correction to QML feasibility',
      'Tóm tắt các nền tảng phần cứng ¦ Liên hệ sửa lỗi với tính khả thi của QML',
      'Platforms: superconducting qubits, trapped ions, neutral atoms, photonics ¦ Error rates and limited qubit counts restrict circuit depth today ¦ Fault-tolerant machines with error-corrected logical qubits are needed for algorithms such as HHL ¦ IBM 2023 experiments claim useful results beyond brute-force classical simulation of a specific model using error mitigation ¦ Plan experiments with realistic circuit sizes.',
      'Nền tảng: qubit siêu dẫn, ion bẫy, nguyên tử trung hoà, quang tử ¦ Tỉ lệ lỗi và số qubit hạn chế giới hạn độ sâu mạch hiện nay ¦ Cần máy chịu lỗi với qubit logic được sửa lỗi cho thuật toán như HHL ¦ Thí nghiệm IBM 2023 tuyên bố có kết quả hữu ích vượt mô phỏng cổ điển vét cạn cho một mô hình cụ thể nhờ giảm thiểu lỗi ¦ Lên kế hoạch thí nghiệm với kích thước mạch thực tế.',
      'Hardware limits shape algorithms ¦ Fault tolerance is the long-term goal ¦ Choose realistic circuit sizes',
      'Phần cứng giới hạn thuật toán ¦ Chịu lỗi là mục tiêu dài hạn ¦ Chọn kích thước mạch thực tế',
      [[YT('PI8PqARCwWo'), 'Qiskit Lecture 9.1: Introduction to quantum hardware', 'Watch the lecture.', 'Xem bài giảng.'],
       ['https://quantum-journal.org/papers/q-2018-08-06-79/', 'Preskill: Quantum Computing in the NISQ era and beyond (Quantum)', 'Read the published version.', 'Đọc bản đã xuất bản.'],
       ['https://www.nature.com/articles/s41586-023-06096-3', 'Kim et al.: Evidence for the utility of quantum computing before fault tolerance', 'Read the abstract.', 'Đọc tóm tắt.'],
       ['https://www.nobelprize.org/prizes/physics/2022/press-release/', 'Nobel Prize in Physics 2022', 'Read the press release on entanglement experiments.', 'Đọc thông cáo về thí nghiệm vướng víu.']]],
    [['Capstone: a quantum classifier project', 'Đồ án cuối môn: dự án bộ phân loại lượng tử'],
      'Plan, implement and critique a QML experiment ¦ Report results honestly',
      'Lập kế hoạch, cài đặt và phê bình một thí nghiệm QML ¦ Báo cáo kết quả trung thực',
      'Pick a small dataset (iris, a two-class subset of MNIST after PCA to 4-8 features) ¦ Implement a quantum kernel SVM and a variational classifier ¦ Choose the encoding with reasons ¦ Run noiseless first, then with a noise model ¦ Tune a classical SVM and logistic regression as baselines ¦ Report accuracy with error bars, circuit cost and training time ¦ Discuss barren plateaus, noise and whether the quantum model adds value.',
      'Chọn bộ dữ liệu nhỏ (iris, hoặc tập con hai lớp của MNIST sau khi PCA xuống 4-8 đặc trưng) ¦ Cài đặt SVM kernel lượng tử và bộ phân loại biến phân ¦ Chọn mã hoá có lý do ¦ Chạy không nhiễu trước, sau đó với mô hình nhiễu ¦ Chỉnh SVM và hồi quy logistic cổ điển làm mốc ¦ Báo cáo độ chính xác kèm sai số, chi phí mạch và thời gian huấn luyện ¦ Bàn về cao nguyên cằn cỗi, nhiễu và việc mô hình lượng tử có thêm giá trị hay không.',
      'Compare against tuned classical baselines ¦ Report error bars and costs ¦ Be honest about advantage',
      'So với mốc cổ điển đã chỉnh ¦ Báo cáo sai số và chi phí ¦ Trung thực về lợi thế',
      [[PL('tutorial_kernel_based_training'), 'PennyLane: kernel-based training with scikit-learn', 'Use as the starting code for the kernel part.', 'Dùng làm mã khởi đầu cho phần kernel.'],
       [PL('tutorial_variational_classifier'), 'PennyLane: variational classifier', 'Use as the starting code for the variational part.', 'Dùng làm mã khởi đầu cho phần biến phân.'],
       ['https://scikit-learn.org/stable/modules/generated/sklearn.decomposition.PCA.html', 'scikit-learn PCA', 'Reduce features before encoding.', 'Giảm đặc trưng trước khi mã hoá.'],
       [YT('ChPLYpUzsY4'), 'Qiskit Summer School 2024: Exploring Quantum Machine Learning', 'Watch for a modern end-to-end workflow.', 'Xem để biết quy trình hiện đại trọn vẹn.']]],
  ]),
];
